  add(/скорост|равномерн|механическое движение|путь(?![а-я])|кинематик|перемещени/, "v = s / t;  s = vt;  t = s / v", r => { const s = pk(r, [90, 120, 150, 180, 240]), t = pk(r, [2, 3, 5, 6]); return [`Автомобиль проехал ${s} км за ${t} ч. Найдите его скорость в км/ч и в м/с.`, `v = s/t = ${nf(s / t)} км/ч = ${nf(s / t / 3.6)} м/с.`]; }, r => { const v1 = pk(r, [54, 72, 90]), v2 = pk(r, [36, 45, 60]), S = pk(r, [180, 270, 360, 450]); return [`Два автомобиля выехали навстречу друг другу из пунктов, расстояние между которыми ${S} км, со скоростями ${v1} км/ч и ${v2} км/ч. Через какое время они встретятся?`, `Скорость сближения v₁ + v₂ = ${v1 + v2} км/ч; t = S/(v₁ + v₂) = ${nf(S / (v1 + v2))} ч.`]; }, r => { const s1 = pk(r, [60, 90]), v1 = pk(r, [30, 45]), s2 = pk(r, [60, 120]), v2 = pk(r, [60, 90]); return [`Первые ${s1} км пути поезд шёл со скоростью ${v1} км/ч, следующие ${s2} км — со скоростью ${v2} км/ч. Найдите среднюю скорость на всём пути.`, `t₁ = ${nf(s1 / v1)} ч, t₂ = ${nf(s2 / v2)} ч; v ср = (s₁ + s₂)/(t₁ + t₂) = ${nf((s1 + s2) / (s1 / v1 + s2 / v2))} км/ч. (Не среднее арифметическое скоростей!)`]; });
  add(/ускорени|равноускорен/, "a = (v − v₀)/t;  s = v₀t + at²/2;  s = (v² − v₀²)/2a", r => { const v0 = pk(r, [0, 2, 4]), v = pk(r, [10, 12, 16, 20]), t = pk(r, [2, 4, 5]); return [`За ${t} с скорость тела изменилась от ${v0} до ${v} м/с. Найдите ускорение.`, `a = (v − v₀)/t = (${v} − ${v0})/${t} = ${nf((v - v0) / t)} м/с².`]; }, r => { const a = pk(r, [1, 2, 3]), t = pk(r, [4, 5, 10]); return [`Из состояния покоя тело движется с ускорением ${a} м/с² в течение ${t} с. Найдите скорость в конце движения и пройденный путь.`, `v = at = ${a * t} м/с; s = at²/2 = ${nf(a * t * t / 2)} м.`]; }, r => { const v0 = pk(r, [54, 72, 108]), a = pk(r, [2, 3, 5]); const v = v0 / 3.6; return [`Автомобиль, двигавшийся со скоростью ${v0} км/ч, тормозит с ускорением ${a} м/с². Найдите время торможения и тормозной путь.`, `v₀ = ${nf(v)} м/с; t = v₀/a = ${nf(v / a)} с; s = v₀²/(2a) = ${nf(v * v / (2 * a))} м.`]; });
  add(/свободн.*падени|падени/, "h = gt²/2;  v = gt;  g = 10 м/с²", r => { const t = pk(r, [2, 3, 4]); return [`Камень падает без начальной скорости ${t} с. Найдите высоту падения и скорость в конце (g = 10 м/с²).`, `h = gt²/2 = ${nf(g * t * t / 2)} м; v = gt = ${g * t} м/с.`]; }, r => { const h = pk(r, [20, 45, 80, 125]); return [`С высоты ${h} м падает тело. Сколько времени оно падает и какова скорость у земли? (g = 10 м/с², сопротивление не учитывать.)`, `t = √(2h/g) = ${nf(Math.sqrt(2 * h / g))} с; v = gt = ${nf(g * Math.sqrt(2 * h / g))} м/с.`]; }, r => { const v0 = pk(r, [20, 30, 40]); return [`Мяч брошен вертикально вверх со скоростью ${v0} м/с. Найдите максимальную высоту подъёма и время подъёма (g = 10 м/с²).`, `H = v₀²/(2g) = ${nf(v0 * v0 / (2 * g))} м; t = v₀/g = ${nf(v0 / g)} с.`]; });
  add(/окружност|центростремительн|круговое|вращательн/, "a = v²/R;  v = 2πR/T;  ν = 1/T", r => { const v = pk(r, [5, 10, 20]), R = pk(r, [25, 50, 100]); return [`Автомобиль едет по закруглению радиусом ${R} м со скоростью ${v} м/с. Найдите центростремительное ускорение.`, `a = v²/R = ${nf(v * v / R)} м/с².`]; }, r => { const R = pk(r, [0.3, 0.5, 2]), T = pk(r, [0.5, 1, 2]); return [`Точка движется по окружности радиусом ${num(R)} м с периодом ${num(T)} с. Найдите линейную скорость, частоту и центростремительное ускорение.`, `ν = 1/T = ${nf(1 / T)} Гц; v = 2πR/T = ${nf(2 * Math.PI * R / T)} м/с; a = v²/R = ${nf(Math.pow(2 * Math.PI * R / T, 2) / R)} м/с².`]; }, r => { const v = pk(r, [10, 15, 20]), R = pk(r, [50, 100]); return [`На повороте радиусом ${R} м автомобиль движется со скоростью ${v} м/с. Каким должен быть коэффициент трения шин о дорогу, чтобы машину не заносило? (g = 10 м/с².)`, `μ ≥ v²/(gR) = ${nf(v * v / (g * R))}.`]; });
  add(/равнодействующ|сложение сил|принцип суперпозиции сил/, "F = F₁ + F₂ (вдоль одной прямой);  F = √(F₁² + F₂²) (под прямым углом)", r => { const a = pk(r, [30, 40, 60]), b = pk(r, [10, 20, 50]); return [`Два человека тянут тележку в одну сторону с силами ${a} Н и ${b} Н. Найдите равнодействующую.`, `F = F₁ + F₂ = ${a + b} Н.`]; }, r => { const a = pk(r, [80, 100, 120]), b = pk(r, [30, 50, 60]); return [`Два мальчика тянут верёвку в противоположные стороны с силами ${a} Н и ${b} Н. Чему равна равнодействующая и куда она направлена?`, `F = ${a} − ${b} = ${a - b} Н; в сторону большей силы.`]; }, r => { const [a, b] = pk(r, [[3, 4], [6, 8], [5, 12]]); return [`Две силы ${a} Н и ${b} Н действуют на тело под прямым углом. Найдите равнодействующую.`, `F = √(F₁² + F₂²) = ${nf(Math.hypot(a, b))} Н.`]; });
  add(/физические величины|цена деления|измерение физических|погрешност/, "C = (x₂ − x₁)/n;  Δx = C/2;  ε = Δx/x · 100 %", r => { const x1 = pk(r, [0, 20]), x2 = pk(r, [40, 60, 100]), n = pk(r, [4, 5, 10]); return [`Между метками ${x1} мл и ${x2} мл на шкале мензурки ${n} промежутков. Найдите цену деления.`, `C = (x₂ − x₁)/n = ${nf((x2 - x1) / n)} мл.`]; }, r => { const a = pk(r, [36, 72, 108]), m = pk(r, [250, 450, 800]); return [`Выразите в единицах СИ: ${a} км/ч, ${m} г, 5 см², 2 мин.`, `${a} км/ч = ${nf(a / 3.6)} м/с; ${m} г = ${nf(m / 1000)} кг; 5 см² = 5·10⁻⁴ м²; 2 мин = 120 с.`]; }, r => { const x = pk(r, [12, 24, 50]), d = pk(r, [0.5, 1]); return [`Длину бруска измерили линейкой с ценой деления ${num(d * 2)} мм и получили ${x} мм. Запишите результат с абсолютной погрешностью и найдите относительную погрешность.`, `Δx = C/2 = ${num(d)} мм; x = (${x} ± ${num(d)}) мм; ε = Δx/x·100 % = ${nf(d / x * 100)} %.`]; });
  add(/ньютон|динамик|сила и ускорение|второй закон|инерци|взаимодействие тел|под действием/, "F = ma;  a = F/m", r => { const m = pk(r, [2, 5, 10]), a = pk(r, [2, 3, 4]); return [`Какая сила сообщает телу массой ${m} кг ускорение ${a} м/с²?`, `F = ma = ${m * a} Н.`]; }, r => { const m = pk(r, [500, 800, 1000]), F = pk(r, [1500, 2000, 3000]), Ft = pk(r, [500, 600, 800]); return [`Автомобиль массой ${m} кг разгоняется силой тяги ${F} Н; сила сопротивления ${Ft} Н. Найдите ускорение.`, `a = (F − F_с)/m = ${nf((F - Ft) / m)} м/с².`]; }, r => { const m = pk(r, [60, 70, 80]), a = pk(r, [1, 2]); return [`Человек массой ${m} кг стоит в лифте, который ускоренно поднимается с ускорением ${a} м/с². Каков вес человека? (g = 10 м/с².)`, `P = m(g + a) = ${m * (g + a)} Н (больше силы тяжести ${m * g} Н — перегрузка).`]; });
