    const probs = probsOf(p, 3), hwp = probsOf(p, 3, "hw"), Q = qualOf(p, kind, terms), fo = formulasOf(p, kind), acts = actsOf(F), lab = kind === "lab" ? labOf(p) : null;
    if (/^Организационный/.test(st)) return { t: kind === "lab" ? "Приветствует класс, проверяет готовность: оборудование на столах по списку, тетрадь, ручка, калькулятор. Напоминает: работа в парах, оборудование берут только по разрешению." : "Приветствует класс, проверяет готовность: учебник, тетрадь, калькулятор; демонстрационный стол подготовлен.", s: "Настраиваются на работу, проверяют рабочее место.", u: "Регулятивные: самоорганизация." };
